<script setup lang="ts">
import {t,uiLanguage,localeTag} from './ui-language'
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,post,ApiError,type Task} from './api'
import ExampleInputs from './ExampleInputs.vue'
import AccountAccess from './AccountAccess.vue'
import PolicyLinks from './PolicyLinks.vue'
import AppLogo from './AppLogo.vue'
import AuthStory from './AuthStory.vue'
import LanguageSwitcher from './LanguageSwitcher.vue'

type CourseTask=Task&{sourceLanguage?:string;mode?:string;createdAt?:string;inputs?:Record<string,any>}
const route=useRoute(),router=useRouter()
const page=computed(()=>route.path.split('/')[1]||'home')
const titles:Record<string,string>={home:'任务工作台',create:'新建课程',results:'结果中心',settings:'设置',task:'任务详情',login:'登录',register:'注册',agents:'制作流程'}
const languages=[['zh-CN','中文','ZH'],['en-US','英语','EN'],['ja-JP','日语','JA'],['ko-KR','韩语','KO'],['de-DE','德语','DE'],['fr-FR','法语','FR'],['ru-RU','俄语','RU'],['es-ES','西班牙语','ES']]
const stageTitles=['课件与讲稿','翻译与校验','语音生成','数字人生成','视频与字幕']
const statusNames:Record<string,string>={queued:'已排队',processing:'生成中',running:'生成中',completed:'已完成',failed:'需处理',waiting_input:'待补充',cancelled:'已取消',needs_regeneration:'需处理',needs_review:'待审核'}
const user=ref<any>(null),ready=ref(false),busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),mediaReady=ref(false),connected=ref(false)
const tasks=ref<CourseTask[]>([]),selected=ref<CourseTask>(),filter=ref('all')
const agreementRequired=ref(false),mediaAuthorized=ref(false),mediaVersion=ref('')
const form=ref({name:'',mode:'upload',topic:'',sourceLanguage:'zh-CN',targetLanguages:['zh-CN'],totalPages:5,durationMinutes:5})
const ppt=ref<File>(),photo=ref<File>(),audio=ref<File>(),script=ref<File>(),photoPreview=ref(''),uploadProgress=ref('')
const pptInput=ref<HTMLInputElement>(),photoInput=ref<HTMLInputElement>(),cameraInput=ref<HTMLInputElement>(),audioInput=ref<HTMLInputElement>(),scriptInput=ref<HTMLInputElement>()
const downloadBusy=ref('')
const exampleBusy=ref(false)
async function useExample({kind,item}:{kind:string;item:any}){
 if(exampleBusy.value||busy.value)return
 exampleBusy.value=true;error.value='';notice.value='';if(['bundle','image','audio'].includes(kind))mediaAuthorized.value=false
 try{
  const getFile=async(url:string,name:string,type:string)=>{const response=await fetch(url);if(!response.ok)throw Error('示例材料暂时无法读取，请稍后重试。');return new File([await response.blob()],name,{type})}
  const definitions:Record<string,[string,string,string]>={ppt:[item.ppt,item.name+'.pptx','application/vnd.openxmlformats-officedocument.presentationml.presentation'],script:[item.script,item.name+'-逐页讲稿.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document'],image:[item.image,'AI虚构讲师-'+item.id+'-512.png','image/png'],audio:[item.audio,'系统示例声音-'+item.id+'.wav','audio/wav']}
  const needed=kind==='bundle'?['ppt','script','image','audio']:kind==='topic'?[]:[kind]
  const files=await Promise.all(needed.map(key=>getFile(...definitions[key]!)))
  if(kind==='bundle'||kind==='topic'){
   clearFiles();form.value={name:item.name,mode:kind==='bundle'?'upload':'topic',topic:item.topic,sourceLanguage:item.sourceLanguage,targetLanguages:[...item.targetLanguages],totalPages:2,durationMinutes:2}
  }
  needed.forEach((key,index)=>{
   if(key==='ppt'){ppt.value=files[index];form.value.mode='upload';form.value.name=item.name;form.value.sourceLanguage=item.sourceLanguage;form.value.targetLanguages=[...item.targetLanguages]}
   if(key==='script')script.value=files[index]
   if(key==='image'){if(photoPreview.value)URL.revokeObjectURL(photoPreview.value);photo.value=files[index];photoPreview.value=URL.createObjectURL(files[index]!)}
   if(key==='audio')audio.value=files[index]
  })
  notice.value=kind==='bundle'?'整套示例已填写，包括课件、逐页讲稿、512×512 虚构人像、参考音频和目标语言。检查后再提交。':kind==='topic'?'课程主题、原语言和目标语言已填写，请选择人像及参考声音。':'示例材料已选择。课件与讲稿请使用同名配套材料；确认目标语言后再提交。'
 }catch(e){error.value=(e as Error).message}finally{exampleBusy.value=false}
}
const translationPolicy=ref({semantic_similarity:.85,terminology_coverage:.9,formula_number_proper_name_accuracy:1,contextual_consistency:.85,maxRetries:1})
const done=computed(()=>tasks.value.filter(t=>t.status==='completed'))
const isActive=(task:CourseTask)=>['processing','running'].includes(task.status)||(task.status==='queued'&&!!task.queue)
const taskStatus=(task:CourseTask)=>task.status==='queued'&&!task.queue?'待生成':statusNames[task.status]||task.status
const active=computed(()=>tasks.value.filter(isActive))
const filtered=computed(()=>tasks.value.filter(t=>filter.value==='all'||(filter.value==='active'?isActive(t):filter.value==='attention'?['failed','waiting_input','needs_regeneration'].includes(t.status):t.status===filter.value)))
const outputEntries=(task:CourseTask)=>Object.entries((task.outputs?.s5 as any)?.languages||{}) as [string,any][]
const displayName=computed(()=>user.value?.displayName||user.value?.name||'课程老师')
const account=computed(()=>user.value?.phone||user.value?.account||'')
const languageName=(value:string)=>t(languages.find(x=>x[0]===value||x[1]===value)?.[1]||value)
const time=(value?:string)=>value?new Date(value).toLocaleString(localeTag(),{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):''
const duration=(value:any)=>{const seconds=Math.round(Number(value)||0);return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')}
const size=(file?:File)=>file?file.size<1024*1024?Math.ceil(file.size/1024)+' KB':(file.size/1024/1024).toFixed(1)+' MB':''
function go(path:string){error.value='';notice.value='';router.push(path);window.scrollTo({top:0,behavior:'instant' as ScrollBehavior})}
function clearFiles(){ppt.value=undefined;photo.value=undefined;audio.value=undefined;script.value=undefined;if(photoPreview.value)URL.revokeObjectURL(photoPreview.value);photoPreview.value='';uploadProgress.value='';mediaAuthorized.value=false}
function clearAccount(){sessionStorage.removeItem('smartcourse-token');sessionStorage.removeItem('smartcourse-user');user.value=null;tasks.value=[];selected.value=undefined;clearFiles();agreementRequired.value=false;form.value={name:'',mode:'upload',topic:'',sourceLanguage:'zh-CN',targetLanguages:['zh-CN'],totalPages:5,durationMinutes:5};translationPolicy.value={semantic_similarity:.85,terminology_coverage:.9,formula_number_proper_name_accuracy:1,contextual_consistency:.85,maxRetries:1}}
async function health(){try{const value=await api<any>('/v1/health');connected.value=value.status==='ok';mediaReady.value=['RUNNING','LOCAL'].includes(value.mediaService)}catch{connected.value=false;mediaReady.value=false}}
async function loadTasks(){const owner=user.value?.id;if(!owner)return;loading.value=true;try{const rows=await api<CourseTask[]>('/v1/tasks');if(owner===user.value?.id)tasks.value=rows}catch(e){if(owner===user.value?.id)error.value=(e as Error).message}finally{if(owner===user.value?.id)loading.value=false}}
async function loadTask(){const owner=user.value?.id,id=String(route.query.id||'');if(!owner||!id)return;try{const row=await api<CourseTask>('/v1/tasks/'+encodeURIComponent(id));if(owner===user.value?.id&&String(route.query.id)===id)selected.value=row}catch(e){if(owner===user.value?.id)error.value=(e as Error).message}}
async function accountAuthenticated(result:any){
 clearFiles();tasks.value=[];selected.value=undefined
 if(result.accessToken)sessionStorage.setItem('smartcourse-token',result.accessToken)
 sessionStorage.setItem('smartcourse-user',JSON.stringify(result.user));user.value=result.user;agreementRequired.value=false
 go('/home');await loadTasks()
}
async function logout(){busy.value=true;try{await post('/v1/auth/logout',{});clearAccount();go('/login')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function loadPolicy(){const owner=user.value?.id;if(!owner)return;try{const value=await api<typeof translationPolicy.value>('/v1/settings/translation');if(owner===user.value?.id)translationPolicy.value=value}catch(e){error.value=(e as Error).message}}
async function savePolicy(){busy.value=true;try{translationPolicy.value=await api<typeof translationPolicy.value>('/v1/settings/translation',{method:'PUT',body:JSON.stringify(translationPolicy.value)});notice.value='翻译校验参数已保存。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function choose(event:Event,kind:'ppt'|'image'|'audio'|'script'){
 const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return
 error.value=''
 if(kind==='ppt'){if(!/\.(pptx|pdf)$/i.test(file.name)){error.value='请选择 PPTX 或 PDF 课件。';return}if(file.size>80*1024*1024){error.value='手机上传支持 80 MB 以内的课件。';return}ppt.value=file;if(!form.value.name)form.value.name=file.name.replace(/\.(pptx|pdf)$/i,'')}
 if(kind==='image'){mediaAuthorized.value=false;if(!/\.(png|jpe?g|webp)$/i.test(file.name)){error.value='请选择 JPG、PNG 或 WebP 照片。';return}if(photoPreview.value)URL.revokeObjectURL(photoPreview.value);photo.value=file;photoPreview.value=URL.createObjectURL(file)}
 if(kind==='audio'){mediaAuthorized.value=false;audio.value=file}
 if(kind==='script')script.value=file
}
function toggleLanguage(code:string){const index=form.value.targetLanguages.indexOf(code);if(index<0)form.value.targetLanguages.push(code);else form.value.targetLanguages.splice(index,1)}
async function upload(file:File,kind:string){
 const content=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(Error('文件读取失败，请重新选择。'));reader.readAsDataURL(file)})
 return new Promise<any>((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/v1/uploads');xhr.setRequestHeader('Content-Type','application/json');const token=sessionStorage.getItem('smartcourse-token');if(token)xhr.setRequestHeader('Authorization','Bearer '+token);xhr.timeout=180000;xhr.upload.onprogress=e=>{uploadProgress.value=t('正在上传')+file.name+(e.lengthComputable?' · '+Math.round(e.loaded/e.total*100)+'%':'')};xhr.onload=()=>{try{const value=JSON.parse(xhr.responseText);if(xhr.status>=200&&xhr.status<300)resolve(value);else reject(Error(value.message||'文件上传未完成。'))}catch{reject(Error('上传服务暂未就绪，请稍后重试。'))}};xhr.onerror=()=>reject(Error('网络连接中断，请重试。'));xhr.ontimeout=()=>reject(Error('上传超时，请检查网络后重试。'));xhr.send(JSON.stringify({filename:file.name,kind,contentBase64:content,...(['image','audio'].includes(kind)?{mediaConsent:{authorized:mediaAuthorized.value,version:mediaVersion.value}}:{})}))})
}
async function createCourse(){
 if(busy.value||exampleBusy.value)return;error.value='';notice.value=''
 if(!user.value){go('/login');return}
 if(form.value.mode==='upload'&&!ppt.value){error.value='请先选择课程 PPTX 或 PDF。';return}
 if(form.value.mode==='topic'&&!form.value.topic.trim()){error.value='请填写课程主题。';return}
 if(!photo.value){error.value='请上传一张教师照片。';return}
 if(!form.value.targetLanguages.length){error.value='请至少选择一种输出语言。';return}
 if(!mediaAuthorized.value){error.value='请先确认人物照片和参考声音的使用授权。';return}
 busy.value=true;const owner=user.value.id
 try{
  const inputs:any=form.value.mode==='upload'?{ppt:await upload(ppt.value!,'ppt')}:{topic:form.value.topic,totalPages:Number(form.value.totalPages),durationMinutes:Number(form.value.durationMinutes),targetLearners:'高校本科生'}
  if(script.value)inputs.script=await upload(script.value,'script')
  const image=await upload(photo.value,'image'),voice=audio.value?await upload(audio.value,'audio'):null
  if(owner!==user.value?.id)throw Error('登录账号已变化，请重新提交。')
  const task=await post<CourseTask>('/v1/tasks',{name:form.value.name.trim()||form.value.topic.trim().slice(0,30)||'我的课程',mode:form.value.mode,sourceLanguage:form.value.sourceLanguage,targetLanguages:form.value.targetLanguages,inputs,autoExecute:false})
  await api('/v1/tasks/'+task.id+'/assets',{method:'PUT',body:JSON.stringify({referenceImage:image,...(voice?{referenceAudio:voice}:{})})})
  await health()
  if(mediaReady.value){try{await post('/v1/tasks/'+task.id+'/execute',{startStage:1})}catch(e){if(e instanceof ApiError&&e.status===409){await health();if(mediaReady.value)throw e}else throw e}}
  clearFiles();selected.value=task;go('/task?id='+task.id)
  if(!mediaReady.value)notice.value='素材和任务已保存。生成服务恢复后，可点击“开始生成”。'
  await loadTask();await loadTasks()
 }catch(e){error.value=(e as Error).message}finally{busy.value=false;uploadProgress.value=''}
}
async function execute(task:CourseTask){error.value='';const startStage=task.stages.find(x=>x.status!=='completed')?.index||1;await health();if(startStage<5&&!mediaReady.value){notice.value='生成算力暂未启动，已上传素材会保留。';return}busy.value=true;try{await post('/v1/tasks/'+task.id+'/execute',{startStage});await loadTask();await loadTasks()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function cancelTask(task:CourseTask){busy.value=true;try{await post('/v1/tasks/'+task.id+'/cancel',{});await loadTask();await loadTasks()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function download(path:string,name:string){downloadBusy.value=path;try{const token=sessionStorage.getItem('smartcourse-token');const response=await fetch(path,{headers:token?{Authorization:'Bearer '+token}:{}});if(!response.ok)throw Error('文件下载未完成，请重新登录后重试。');const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){error.value=(e as Error).message}finally{downloadBusy.value=''}}
watch(()=>route.fullPath,()=>{error.value='';if(['home','results'].includes(page.value))void loadTasks();if(page.value==='settings')void loadPolicy();if(page.value==='task'){selected.value=undefined;void loadTask()}})
watch(uiLanguage,()=>{error.value='';notice.value=''})
let timer:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{
 await health()
 try{const value=await api<any>('/v1/auth/policies');mediaVersion.value=value.mediaVersion}catch(e){error.value=(e as Error).message}
 try{const result=await post<any>('/v1/auth/session',{});user.value=result.user;agreementRequired.value=!!result.agreementRequired;sessionStorage.setItem('smartcourse-user',JSON.stringify(result.user));if(agreementRequired.value)await router.replace('/login')}
 catch(e){if(e instanceof ApiError&&e.status===401)clearAccount();else error.value=(e as Error).message}
 if(!user.value&&!['login','register'].includes(page.value))await router.replace('/register')
 ready.value=true
 if(user.value&&!agreementRequired.value){await loadTasks();if(page.value==='task')await loadTask();if(page.value==='settings')await loadPolicy()}
 timer=setInterval(()=>{void health();if(user.value&&!agreementRequired.value){if(page.value==='task')void loadTask();else if(['home','results'].includes(page.value))void loadTasks()}},8000)
})
onUnmounted(()=>{if(timer)clearInterval(timer);if(photoPreview.value)URL.revokeObjectURL(photoPreview.value)})
</script>

<template>
 <div class="mobile-shell" :class="{'auth-shell':!user||agreementRequired||['login','register'].includes(page)}">
   <header class="mobile-top">
    <template v-if="!user||agreementRequired||['login','register'].includes(page)"><div class="auth-brand"><AppLogo compact /><div><b>智课工坊</b><small>SMARTCOURSE</small></div></div><LanguageSwitcher /></template>
    <template v-else><button v-if="['task','agents'].includes(page)" :aria-label='t("返回任务")' @click="go('/home')">‹</button><AppLogo v-else compact /><strong>{{t(titles[page]||"智课工坊")}}</strong><LanguageSwitcher /><span class="connection-dot" :class="{online:connected}" :aria-label="connected?t('服务已连接'):t('服务连接中')"></span></template>
   </header>
  <main v-if="!ready" class="mobile-page"><div class="surface empty"><div class="loading-dot"></div><p>{{t("正在进入智课工坊…")}}</p></div></main>
  <main v-else-if="!user||agreementRequired||['login','register'].includes(page)" class="auth-page">
   <div class="auth-layout"><AuthStory /><div class="auth-form-column"><AccountAccess :mode="page==='login'?'login':'register'" :session-user="user" @authenticated="accountAuthenticated" @mode="go('/'+$event)" @logout="logout" /></div></div>
   <footer class="auth-footer"><span>© {{new Date().getFullYear()}} 智课工坊</span><span>哈工大 AISS 组</span></footer>
  </main>
  <main v-else class="mobile-page">
   <p v-if="error" class="error" role="alert">{{t(error)}}</p><p v-if="notice" class="notice" role="status">{{t(notice)}}</p>
   <template v-if="page==='home'">
    <div class="welcome-row"><div><div class="eyebrow">MOOC PRODUCTION DESK</div><h1>{{displayName}}{{t("，欢迎使用")}}</h1><p class="muted">{{user.institution||t("多语种课程制作中心")}}</p></div><div class="avatar-badge">{{displayName.slice(0,1)}}</div></div>
    <section class="hero-card"><div class="hero-grid"></div><div class="hero-content"><p>{{t("从课程素材到多语种视频")}}</p><h2>{{t("多智能体协同驱动")}}<br>{{t("S1—S5 自动生成流程")}}</h2><div class="hero-languages"><span v-for="language in languages" :key="language[0]">{{t(language[1])}}</span></div><button @click="go('/create')">{{t("新建生成任务")}}</button></div><div class="hero-orbit"><div class="orbit-ring ring-one"></div><div class="orbit-ring ring-two"></div><b>AI</b><span class="node-one">课</span><span class="node-two">译</span><span class="node-three">声</span><span class="node-four">人</span></div></section>
    <div class="stats-grid"><div class="surface"><b>{{tasks.length}}</b><span>{{t("全部任务")}}</span></div><div class="surface"><b class="accent">{{active.length}}</b><span>{{t("正在生成")}}</span></div><div class="surface"><b>{{done.length}}</b><span>{{t("已完成")}}</span></div><div class="surface"><b>{{languages.length}}</b><span>{{t("目标语种")}}</span></div></div>
    <div class="section-heading"><div><h2>{{t("生成任务")}}</h2><p>{{t("查看全流程状态与阶段结果")}}</p></div><button class="text-button" @click="go('/agents')">{{t("制作流程")}}</button></div>
    <div class="filters"><button v-for="item in [['all',t('全部')],['active',t('生成中')],['completed',t('已完成')],['attention',t('需处理')]]" :key="item[0]" :class="{chosen:filter===item[0]}" @click="filter=item[0]">{{item[1]}}</button></div>
    <button v-for="task in filtered" :key="task.id" class="surface task-card" @click="go('/task?id='+task.id)"><div class="task-top"><span class="mode-icon">{{task.mode==='topic'?'题':'件'}}</span><div class="task-heading"><h3>{{task.name}}</h3><p>{{task.mode==='topic'?t("课程主题生成"):t("已有课件素材")}} · {{languageName(task.sourceLanguage||t("中文"))}} → {{task.targetLanguages.length}} {{t("个语种")}}</p></div><span class="status-pill" :class="task.status">{{t(taskStatus(task))}}</span></div><div class="language-row"><span v-for="language in task.targetLanguages" :key="language">{{languageName(language)}}</span></div><div class="progress-head"><span>{{t(stageTitles[Math.max(0,task.currentStage-1)])}}</span><b>{{task.overallProgress}}%</b></div><div class="progress-track"><i :style="{width:task.overallProgress+'%'}"></i></div><div class="task-footer"><span>{{time(task.updatedAt)}}</span><b>{{t("查看详情 ›")}}</b></div></button>
    <div v-if="!filtered.length" class="surface empty"><span class="empty-mark">＋</span><h3>{{loading?t("正在读取任务"):t("暂无相关任务")}}</h3><p>{{t("上传教师照片和课件，创建第一份课程视频。")}}</p><button class="text-button" @click="go('/create')">{{t("新建生成任务 ›")}}</button></div>
   </template>
   <template v-else-if="page==='create'">
    <div class="page-heading"><div class="eyebrow">NEW GENERATION TASK</div><h1>{{t("创建课程生成任务")}}</h1><p>{{t("准备教师照片和课件，选择语言后提交。")}}</p></div>
    <ExampleInputs :busy="exampleBusy||busy" @select="useExample" />
    <details class="surface quick-guide" open><summary>{{t("操作引导 · 第一次使用从这里开始")}}</summary><ol><li><b>{{t("准备材料")}}</b>{{t("：上传本人的清晰正面照片，以及 PPTX 或 PDF；也可填写课程主题。")}}</li><li><b>{{t("设置讲解")}}</b>{{t("：需要自己的声音时上传参考音频；已有逐页讲稿时，可在下方上传 DOCX。")}}</li><li><b>{{t("选择语言")}}</b>{{t("：原语言对应输入材料；输出语言决定生成的课件、讲稿、语音及字幕语种。")}}</li><li><b>{{t("提交并查看")}}</b>{{t("：提交后在“任务”查看排队与五阶段进度，完成后在“结果”播放或下载。")}}</li></ol><p>{{t("生成过程中可以关闭页面。同一账号重新登录后，可继续查看任务。算力暂未启动时，材料与任务会先保存。")}}</p></details>
    <h2 class="section-title">{{t("1. 任务信息")}}</h2><section class="surface form-card"><label>{{t("任务名称")}}<input v-model="form.name" :placeholder='t("例如：人工智能概述")'></label><span class="field-label">{{t("任务创建方式")}}</span><div class="mode-list"><button :class="{selected:form.mode==='upload'}" @click="form.mode='upload'"><span>01</span><div><b>{{t("已有课件素材")}}</b><small>{{t("上传 PPTX 或 PDF，自动整理逐页讲稿")}}</small></div><i></i></button><button :class="{selected:form.mode==='topic'}" @click="form.mode='topic'"><span>02</span><div><b>{{t("课程主题生成")}}</b><small>{{t("描述主题，生成课件和配套讲解")}}</small></div><i></i></button></div></section>
    <h2 class="section-title">{{t("2. 教师照片与课程输入")}}</h2><section class="surface form-card"><span class="field-label">{{t("教师照片")}}</span><div class="photo-upload"><img v-if="photoPreview" :src="photoPreview" :alt='t("所选教师照片")'><div v-else class="portrait-symbol"><span></span><i></i></div><div><b>{{photo?t("教师照片已选择"):t("上传一张清晰正面照")}}</b><p>{{photo?photo.name:t("用于生成课程中的讲者形象")}}</p><div class="photo-buttons"><button class="secondary" @click="photoInput?.click()">{{photo?t("更换照片"):t("从相册选择")}}</button><button class="secondary" @click="cameraInput?.click()">{{t("拍照")}}</button></div></div></div><input ref="photoInput" hidden type="file" accept="image/jpeg,image/png,image/webp" @change="choose($event,'image')"><input ref="cameraInput" hidden type="file" accept="image/*" capture="user" @change="choose($event,'image')">
     <p class="photo-guidance">{{t("建议使用 512×512 正方形正面照，人脸居中、头部完整、无遮挡。其他比例会由数字人程序等比缩放并居中裁剪，可能丢失边缘内容。")}}</p>
     <template v-if="form.mode==='upload'"><span class="field-label input-section">{{t("PPT 课件")}}</span><button class="upload-zone" @click="pptInput?.click()"><span class="file-symbol">P</span><b>{{ppt?ppt.name:t("选择 PPTX 或 PDF 文件")}}</b><small>{{ppt?size(ppt)+t(" · 点击重新选择"):t("可从手机文件中选择，支持 80 MB 以内课件")}}</small></button><input ref="pptInput" hidden type="file" accept=".pptx,.pdf" @change="choose($event,'ppt')"></template>
     <template v-else><label class="input-section">{{t("课程主题")}}<textarea v-model="form.topic" rows="4" :placeholder='t("说明课程主题、教学对象及主要内容")'></textarea></label><div class="two-fields"><label>{{t("课件页数")}}<input v-model.number="form.totalPages" type="number" min="1" max="30"></label><label>{{t("目标分钟")}}<input v-model.number="form.durationMinutes" type="number" min="1" max="180"></label></div></template>
     <details class="optional-assets" :open="!!audio||!!script"><summary>{{t("声音与讲稿（可选）")}}</summary><p>{{t("未上传音频时使用系统参考声音。参考音频宜保持单人、清晰、无背景音乐。DOCX 讲稿请按课件页码分段，例如“第1页”“第2页”。")}}</p><button class="secondary file-choice" @click="audioInput?.click()">{{audio?t("已选择声音：")+audio.name:t("选择参考音频")}}</button><input ref="audioInput" hidden type="file" accept=".wav,.mp3,.m4a,.flac,.ogg" @change="choose($event,'audio')"><button v-if="form.mode==='upload'" class="secondary file-choice" @click="scriptInput?.click()">{{script?t("已选择讲稿：")+script.name:t("选择 DOCX 讲稿")}}</button><input ref="scriptInput" hidden type="file" accept=".docx" @change="choose($event,'script')"></details>
    </section>
    <section class="surface media-consent-card"><h3>{{t("人物照片与声音使用授权")}}</h3><p>{{t("用于生成课程中的讲者画面与讲解语音，并随课程任务保存。更换人像或音频后需要重新确认。")}}</p><label><input v-model="mediaAuthorized" type="checkbox"><span>{{t("我确认素材属于本人或已取得相应授权，同意将本次人物照片和参考音频用于上述处理。")}}</span></label><PolicyLinks media-only /></section>
    <h2 class="section-title">{{t("3. 原语言与目标语言")}}</h2><section class="surface form-card"><label>{{t("输入材料原语言")}}<select :value="form.mode==='topic'?'zh-CN':form.sourceLanguage" :disabled="form.mode==='topic'" @change="form.sourceLanguage=($event.target as HTMLSelectElement).value"><option v-for="language in languages" :key="language[0]" :value="language[0]">{{t(language[1])}}</option></select></label><p class="language-help">{{t("目标语言可多选，用于生成对应语种的课件、讲稿、语音、字幕和视频。")}}</p><div class="language-grid"><button v-for="language in languages" :key="language[0]" :class="{selected:form.targetLanguages.includes(language[0])}" :aria-pressed="form.targetLanguages.includes(language[0])" @click="toggleLanguage(language[0])"><b>{{language[2]}}</b><span>{{t(language[1])}}</span><i>{{form.targetLanguages.includes(language[0])?'✓':''}}</i></button></div><p class="selected-language" role="status">{{t("原语言：")}}{{languageName(form.mode==='topic'?'zh-CN':form.sourceLanguage)}} {{t("→ 目标语言：")}}{{form.targetLanguages.length?form.targetLanguages.map(languageName).join('、'):t("尚未选择")}}</p></section>
    <div class="process-preview"><span v-for="(title,index) in stageTitles" :key="title"><b>{{index+1}}</b>{{t(title)}}</span></div><p v-if="!mediaReady" class="notice">{{t("生成算力暂未启动。可先保存照片、课件和任务。")}}</p><p v-if="uploadProgress" class="upload-progress" role="status">{{t(uploadProgress)}}</p><button class="primary submit-button" :disabled="busy||exampleBusy" @click="createCourse">{{busy?t("正在提交…"):mediaReady?t("创建并开始生成"):t("保存课程任务")}}</button><p class="submit-caption">{{t("进度与完成的视频可在“任务”和“结果”中查看")}}</p>
   </template>
   <template v-else-if="page==='task'">
    <template v-if="selected"><section class="task-hero"><span>{{selected.mode==='topic'?t("课程主题生成"):t("PPT 课件解析")}}</span><h1>{{selected.name}}</h1><p>{{selected.targetLanguages.map(languageName).join(' · ')}}</p><div class="progress-head"><span>{{t(taskStatus(selected))}}</span><b>{{selected.overallProgress}}%</b></div><div class="progress-track"><i :style="{width:selected.overallProgress+'%'}"></i></div><small>{{t("最近更新")}} {{time(selected.updatedAt)}}</small></section><p v-if="selected.queue?.message" class="notice">{{t(selected.queue.message)}}</p><p v-if="selected.error?.message" class="error">{{t(selected.error.message)}}</p><h2 class="section-title">{{t("五阶段处理进度")}}</h2><div class="stage-list"><details v-for="stage in selected.stages" :key="stage.index" class="surface stage-card"><summary><span class="stage-number" :class="{finished:stage.status==='completed'}">{{stage.status==='completed'?'✓':stage.index}}</span><div><b>{{t(stageTitles[stage.index-1])}}</b><small>{{t((stage.status==='queued'&&!selected.queue?t("等待执行"):statusNames[stage.status])||({'pending':t("等待执行"),'waiting':t("等待执行")} as Record<string,string>)[stage.status]||stage.status)}}</small></div><span class="stage-percent">{{stage.progress||0}}%</span></summary><p v-if="stage.detail?.step">{{t(stage.detail.step)}}</p><div class="progress-track"><i :style="{width:(stage.progress||0)+'%'}"></i></div></details></div><div v-if="selected.status!=='completed'" class="task-actions"><button v-if="!['processing','running'].includes(selected.status)" class="primary" :disabled="busy" @click="execute(selected)">{{['failed','waiting_input','needs_regeneration'].includes(selected.status)?t("继续生成"):t("开始生成")}}</button><button v-if="['queued','processing','running'].includes(selected.status)" class="secondary" :disabled="busy" @click="cancelTask(selected)">{{t("取消任务")}}</button></div><template v-if="outputEntries(selected).length"><h2 class="section-title">{{t("课程视频与文件")}}</h2><section v-for="[language,output] in outputEntries(selected)" :key="language" class="surface result-card"><h3>{{languageName(language)}}</h3><video v-if="output.video||output.finalVideo" :src="output.video||output.finalVideo" controls playsinline preload="metadata"></video><div class="result-actions"><button v-if="output.video||output.finalVideo" class="primary" :disabled="!!downloadBusy" @click="download(output.video||output.finalVideo,selected.name+'-'+language+'.mp4')">{{t("下载视频")}}</button><button v-if="output.srt" class="secondary" :disabled="!!downloadBusy" @click="download(output.srt,selected.name+'-'+language+'.srt')">{{t("字幕")}}</button><button v-if="output.downloadBundle" class="secondary" :disabled="!!downloadBusy" @click="download(output.downloadBundle,selected.name+'-'+language+'.zip')">{{t("完整文件")}}</button></div></section></template></template><div v-else class="surface empty"><p>{{t("正在读取任务…")}}</p></div>
   </template>
   <template v-else-if="page==='results'"><div class="page-heading"><div class="eyebrow">GENERATED OUTPUTS</div><h1>{{t("结果中心")}}</h1><p>{{t("预览和下载已完成的课程视频。")}}</p></div><section v-for="task in done" :key="task.id" class="surface result-card"><video v-if="outputEntries(task)[0]?.[1]?.video" :src="outputEntries(task)[0]?.[1]?.video" controls playsinline preload="metadata"></video><div class="result-copy"><h3>{{task.name}}</h3><div class="language-row"><span v-for="language in task.targetLanguages" :key="language">{{languageName(language)}}</span></div><p>{{time(task.updatedAt)}} <span v-if="outputEntries(task)[0]?.[1]?.durationSeconds">· {{duration(outputEntries(task)[0]?.[1]?.durationSeconds)}}</span></p></div><button class="secondary" @click="go('/task?id='+task.id)">{{t("视频与文件 ›")}}</button></section><div v-if="!done.length" class="surface empty"><span class="empty-mark">影</span><h3>{{t("暂无已完成结果")}}</h3><p>{{t("完成的视频会显示在这里，生成过程中可关闭页面稍后查看。")}}</p><button class="text-button" @click="go('/home')">{{t("查看我的任务 ›")}}</button></div></template>
   <template v-else-if="page==='settings'"><section class="surface profile-card"><div class="avatar-badge">{{displayName.slice(0,1)}}</div><div><h2>{{displayName}}</h2><p>{{user.institution}}</p><small>{{account}}</small></div><span class="status-pill completed">{{t("已登录")}}</span></section><h2 class="section-title">{{t("系统状态")}}</h2><section class="surface settings-card"><div><span>{{t("课程任务服务")}}</span><b :class="{accent:connected}">{{connected?t("已连接"):t("连接中")}}</b></div><div><span>{{t("视频生成算力")}}</span><b>{{mediaReady?t("可生成"):t("暂未启动")}}</b></div><p>{{t("任务和素材按账号分别保存，可稍后回来查看进度。")}}</p></section><h2 class="section-title">{{t("翻译校验参数")}}</h2><section class="surface settings-card"><label class="mobile-threshold">{{t("语义相似度阈值")}}<input v-model.number="translationPolicy.semantic_similarity" type="number" min="0.85" max="1" step="0.01"></label><label class="mobile-threshold">{{t("术语覆盖率阈值")}}<input v-model.number="translationPolicy.terminology_coverage" type="number" min="0.9" max="1" step="0.01"></label><label class="mobile-threshold">{{t("最大自动修正次数")}}<input v-model.number="translationPolicy.maxRetries" type="number" min="0" max="3" step="1"></label><button class="secondary" :disabled="busy" @click="savePolicy">{{t("保存校验参数")}}</button></section><h2 class="section-title">{{t("协议与隐私")}}</h2><section class="surface settings-card"><PolicyLinks /><p>{{t("协议同意与素材处理授权分别确认。")}}</p></section><h2 class="section-title">{{t("账号管理")}}</h2><section class="surface settings-card"><button class="logout" :disabled="busy" @click="logout">{{t("退出登录")}} <span>›</span></button></section><p class="version-info">{{t("智课工坊 · 多语种课程视频生成")}}</p></template>
   <template v-else-if="page==='agents'"><div class="page-heading"><div class="eyebrow">COURSE PRODUCTION</div><h1>{{t("从课件到课程视频")}}</h1><p>{{t("照片和课件提交后，按以下顺序处理。")}}</p></div><section v-for="(title,index) in stageTitles" :key="title" class="surface process-card"><span class="stage-number">{{index+1}}</span><div><h3>{{t(title)}}</h3><p>{{[t("读取课件内容，整理逐页讲稿。"),t("生成目标语言课件和讲稿，并检查术语。"),t("根据讲稿与所选声音生成讲解音频。"),t("结合教师照片和音频生成人物视频。"),t("合成课件、人物、声音和字幕，提供下载。")][index]}}</p></div></section></template>
  </main>
  <nav v-if="user&&!agreementRequired&&!['login','register'].includes(page)" class="bottom-nav" :aria-label='t("主要导航")'><button v-for="item in [['home',t('任务'),'▤'],['create',t('新建'),'＋'],['results',t('结果'),'▷'],['settings',t('设置'),'⚙']]" :key="item[0]" :class="{active:page===item[0]||(page==='task'&&item[0]==='home')}" @click="go('/'+item[0])"><span>{{item[2]}}</span><small>{{item[1]}}</small></button></nav>
 </div>
</template>

<style>
*{box-sizing:border-box}body{margin:0;background:#e8edeb;color:#1d252c;font:14px/1.55 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}button,input,textarea,select{font:inherit}button{cursor:pointer;border:0}button:disabled{opacity:.55;cursor:wait}button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #7ec4af;outline-offset:3px}input,textarea,select{width:100%;min-width:0;border:1px solid #e2e7e4;border-radius:10px;padding:12px;color:#22372e;background:#f8faf9;font-size:16px;outline:none}input:focus,textarea:focus,select:focus{border-color:#358670;background:white}input[hidden]{display:none}button.primary,.primary{width:100%;min-height:46px;border-radius:10px;background:#176b5b;color:white;font-weight:650;padding:12px 16px;box-shadow:0 5px 12px #176b5b1b}.secondary{min-height:38px;border-radius:9px;padding:9px 14px;background:#e8f3ef;color:#176b5b;font-weight:600}.text-button{background:transparent;color:#176b5b;font-weight:650;padding:6px 0}.muted{color:#7f888e}.accent{color:#176b5b}.mobile-shell{max-width:520px;min-height:100dvh;margin:auto;background:#f4f6f8;box-shadow:0 0 60px #203e3010}.mobile-top{height:56px;padding:0 20px;display:flex;align-items:center;justify-content:space-between;background:#f7f8fa;border-bottom:1px solid #edf0ef;position:sticky;top:0;z-index:20}.mobile-top strong{font-size:16px;font-weight:650}.mobile-top button{font-size:32px;line-height:1;background:transparent;color:#176b5b;width:26px;padding:0;text-align:left}.top-brand{background:#176b5b;color:white;border-radius:7px;width:25px;height:25px;display:grid;place-items:center;font-weight:700}.connection-dot{width:8px;height:8px;border-radius:50%;background:#c5cbc8;margin:0 8px}.connection-dot.online{background:#4e9a7a}.mobile-page{padding:20px 16px calc(100px + env(safe-area-inset-bottom))}.surface{background:white;border:1px solid #e6e9ec;border-radius:14px;box-shadow:0 5px 16px #20303906}.eyebrow{font-size:10px;letter-spacing:1.4px;fo